function textValue(...values) {
  for (const value of values) {
    const text = String(value || '').trim();
    if (text) return text;
  }
  return '';
}

function cleanText(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function truncateText(value, max) {
  const text = cleanText(value);
  if (text.length <= max) return text;
  return text.slice(0, Math.max(0, max - 3)).trimEnd() + '...';
}

function bodyText(value, max) {
  const text = String(value || '')
    .replace(/[ \t\f\v]+/g, ' ')
    .replace(/\s*\n\s*/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  if (text.length <= max) return text;
  return text.slice(0, Math.max(0, max - 3)).trimEnd() + '...';
}

function compactId(value, fallback) {
  const text = cleanText(value || fallback || '').toLowerCase().replace(/[^a-z0-9_-]+/g, '_').replace(/^_+|_+$/g, '');
  return (text || String(fallback || 'item')).slice(0, 180);
}

function slugPayload(value) {
  return cleanText(value)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

function isModelCode(value) {
  const text = cleanText(value);
  return Boolean(text && !text.includes(' ') && /[_-]/.test(text) && /^[a-z0-9_-]+$/i.test(text));
}

function displayModelName(value) {
  let text = cleanText(value)
    .replace(/__(mas_info|mas_informacion|ver_en_persona|test_drive|test|info)$/i, '')
    .replace(/^catalog_/, '');
  if (!text) return '';
  const shouldHumanize = isModelCode(text) || text === text.toLowerCase();
  if (!shouldHumanize && text.includes(' ')) return text;

  const rawWords = text.replace(/_+/g, ' ').split(/\s+/).filter(Boolean);
  const words = [];
  for (let i = 0; i < rawWords.length; i++) {
    const token = String(rawWords[i] || '').trim();
    const lower = token.toLowerCase();
    if (lower === 'f' && /^\d+$/.test(rawWords[i + 1] || '')) {
      words.push('F-' + rawWords[i + 1]);
      i += 1;
      continue;
    }
    if (/^f-?\d+$/i.test(token)) {
      words.push('F-' + token.replace(/^f-?/i, ''));
      continue;
    }
    if (['xlt', 'st', 'ta', 'tm', 'hev', 'fhev', 'suv'].includes(lower)) {
      words.push(lower.toUpperCase());
      continue;
    }
    if (lower === 'st-line' || lower === 'stline') {
      words.push('ST-Line');
      continue;
    }
    if (lower === 'tgdi') {
      words.push('Hyundai');
      continue;
    }
    words.push(lower.charAt(0).toUpperCase() + lower.slice(1));
  }
  return words.join(' ');
}

function labeledFieldsFromText(value) {
  const text = String(value || '');
  const fields = {};
  const pattern = /(?:^|\s)(button_action|model|button_text|button_payload)\s*:\s*([\s\S]*?)(?=\s+(?:button_action|model|button_text|button_payload)\s*:|$)/gi;
  let match;
  while ((match = pattern.exec(text)) !== null) {
    fields[String(match[1] || '').toLowerCase()] = cleanText(match[2]);
  }
  return fields;
}

