function ecuadorDatePlus(days) {
  const date = new Date(Date.now() + days * 24 * 60 * 60 * 1000);
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Guayaquil',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date).reduce((acc, part) => {
    acc[part.type] = part.value;
    return acc;
  }, {});
  return `${parts.year}-${parts.month}-${parts.day}`;
}

function ecuadorDateInfo(days) {
  const date = new Date(Date.now() + days * 24 * 60 * 60 * 1000);
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/Guayaquil',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    weekday: 'short',
  }).formatToParts(date).reduce((acc, part) => {
    acc[part.type] = part.value;
    return acc;
  }, {});
  return {
    date: `${parts.year}-${parts.month}-${parts.day}`,
    weekday: String(parts.weekday || '').toLowerCase(),
  };
}

function isWeekendDate(value) {
  const [year, month, day] = String(value || '').split('-').map(Number);
  if (!year || !month || !day) return false;
  const weekday = new Date(Date.UTC(year, month - 1, day)).getUTCDay();
  return weekday === 0 || weekday === 6;
}

function nextBusinessDate(startOffsetDays = 1) {
  for (let offset = startOffsetDays; offset <= startOffsetDays + 14; offset += 1) {
    const info = ecuadorDateInfo(offset);
    if (!['sat', 'sun'].includes(info.weekday)) return info.date;
  }
  return ecuadorDatePlus(startOffsetDays);
}

function weekendUnavailableDates(daysAhead = 90) {
  const dates = [];
  for (let offset = 0; offset <= daysAhead; offset += 1) {
    const info = ecuadorDateInfo(offset);
    if (['sat', 'sun'].includes(info.weekday)) dates.push(info.date);
  }
  return dates;
}

function normalizeDate(value, fallback) {
  const match = String(value || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
  return match ? `${match[1]}-${match[2]}-${match[3]}` : fallback;
}

function normalizeTime(value, fallback) {
  const match = String(value || '').match(/^(\d{1,2}):(\d{2})/);
  if (!match) return fallback;
  return `${String(Number(match[1])).padStart(2, '0')}:${match[2]}`;
}

