    if (item.name) target.push(item);
  }
}

function pushDirectCatalogItems(target) {
  const sources = [action.catalog_items, action.items, action.options, $json.catalog_items, $json.products];
  for (const source of sources) {
    if (target.length) return;
    pushCatalogItems(target, source);
  }
}

