async function loadCatalogItems(target) {
  pushDirectCatalogItems(target);
  if (target.length) return;

  const mcpBase = textValue(editFields.URL_MCP, $json.URL_MCP).replace(/\/+$/, '');
  if (!mcpBase || typeof $helpers === 'undefined' || typeof $helpers.httpRequest !== 'function') {
    return;
  }

  const urls = [
    `${mcpBase}/api/products/catalog-carousel?segment=all&limit=10&base_only=true`,
    `${mcpBase}/api/products/catalog-carousel?segment=all&limit=10`,
  ];

  for (const url of urls) {
    if (target.length) return;
    try {
      let response = await $helpers.httpRequest({
        method: 'GET',
        url,
      });
      if (typeof response === 'string') response = JSON.parse(response);
      pushCatalogItems(target, Array.isArray(response?.results) ? response.results : []);
    } catch (error) {
      // Try the next MCP catalog source. If all fail, use text fallback.
    }
  }

}

