    const normalized = normalizeActionItems([item])[0];
    if (!normalized) continue;
    const key = String(normalized.id || normalized.name || '').toLowerCase();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    merged.push(normalized);
    if (merged.length >= 10) break;
  }
  return merged;
}

async function loadFullCategoryItems(catalog) {
  const directItems = normalizeActionItems(catalog.items).slice(0, 10);
  const mcpBase = textValue(editFields.URL_MCP, $json.URL_MCP).replace(/\/+$/, '');
  if (!mcpBase || typeof $helpers === 'undefined' || typeof $helpers.httpRequest !== 'function') return directItems;

  const categoryTerms = [catalog.segment, catalog.category, catalog.key, catalog.title]
    .map((value) => cleanText(value))
    .filter((value, idx, values) => value && values.indexOf(value) === idx);
  if (!categoryTerms.length) return directItems;

  let bestItems = directItems;
  for (const term of categoryTerms) {
    const encoded = encodeURIComponent(term);
    const urls = [
      `${mcpBase}/api/products/catalog-carousel?segment=${encoded}&limit=10&base_only=true`,
      `${mcpBase}/api/products/catalog-carousel?segment=${encoded}&limit=10`,
      `${mcpBase}/api/products/catalog-carousel?category=${encoded}&limit=10&base_only=true`,
      `${mcpBase}/api/products/catalog-carousel?category=${encoded}&limit=10`,
    ];
    for (const url of urls) {
      try {
        let response = await $helpers.httpRequest({ method: 'GET', url });
        if (typeof response === 'string') response = JSON.parse(response);
        const responseItems = Array.isArray(response?.results) ? response.results : (Array.isArray(response?.items) ? response.items : []);
        const merged = mergeUniqueCatalogItems(responseItems, directItems);
        if (merged.length > bestItems.length) bestItems = merged;
        if (bestItems.length >= 10) return bestItems.slice(0, 10);
      } catch (error) {
        // Keep the direct MCP next-action items if the category lookup is unavailable.
      }
    }
  }
  return bestItems.slice(0, 10);
}

function buildCatalogCarouselPayload(catalog, text, categoryItems) {
  const allItems = normalizeActionItems(categoryItems || catalog.items).slice(0, 10);
  const items = allItems.filter((item) => isImageUrl(item.image_url)).slice(0, 10);
  if (items.length < 2) return null;
  const cards = items.map((item, idx) => {
    const ids = modelActionIds(item);
    return {
      card_index: idx,
      type: 'cta_url',
      header: { type: 'image', image: { link: item.image_url } },
      body: { text: truncateText([item.name, item.price_from || item.description].filter(Boolean).join('\n'), 160) },
      action: { buttons: [
        { type: 'quick_reply', quick_reply: { id: ids.moreInfo, title: 'Más información' } },
        { type: 'quick_reply', quick_reply: { id: ids.inPerson, title: 'Ver en persona' } },
      ] },
    };
  });
  return {
    body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'carousel',
        body: { text: truncateText(text || catalog.title || 'Modelos Hyundai disponibles', 1024) },
