      } catch (error) {
        // Fallback: if the queue cannot be registered, send the complete sequence immediately so the customer still receives the information.
        for (const queueMessage of queueMessages) {
          await $helpers.httpRequest({
            method: 'POST',
            url: graphUrl,
            headers: {
              Authorization: 'Bearer ' + graphToken,
              'Content-Type': 'application/json',
