const concatenated = $('Concatenar Buffer').item.json || {};
const inputItems = $input.all();
const bufferGuard = inputItems.length && inputItems[0].json ? inputItems[0].json : {};
const raw = Array.isArray(bufferGuard.message) ? bufferGuard.message : (bufferGuard.message ? [bufferGuard.message] : []);
const parsed = [];
for (const entry of raw) {
  let parsedEntry = null;
  try {
    parsedEntry = typeof entry === 'string' ? JSON.parse(entry) : entry;
  } catch (error) {
    parsedEntry = null;
  }
  if (parsedEntry) {
    parsed.push(parsedEntry);
  }
}
for (let i = 1; i < parsed.length; i++) {
  const current = parsed[i];
  const currentTime = new Date((current && current.date_time) || 0).getTime() || 0;
  let j = i - 1;
  while (j >= 0) {
    const previous = parsed[j];
    const previousTime = new Date((previous && previous.date_time) || 0).getTime() || 0;
    if (previousTime <= currentTime) {
      break;
    }
    parsed[j + 1] = previous;
    j -= 1;
  }
  parsed[j + 1] = current;
}
const last = parsed.length ? parsed[parsed.length - 1] : {};
const effectiveMessage = String(base.user_message_for_agent || base.concat_message || concatenated.concat_message || '').trim();
const output = Object.assign({}, base, {
  concat_message: effectiveMessage,
  user_message_for_agent: effectiveMessage,
  buffer_items: concatenated.buffer_items || parsed,
  buffer_items_count: Number(concatenated.buffer_items_count != null ? concatenated.buffer_items_count : parsed.length),
  buffer_last_message_id: concatenated.buffer_last_message_id || String((last && last.message_id) || ''),
  buffer_last_message_text: concatenated.buffer_last_message_text || (last && (last.data || last.content_text)) || '',
  buffer_signature: concatenated.buffer_signature || '',
  effective_user_message: effectiveMessage,
  effective_message_source: base.user_message_for_agent ? 'set_conversation_intent.user_message_for_agent' : (base.concat_message ? 'set_conversation_intent.concat_message' : 'concatenar_buffer.concat_message'),
  guard_buffer_last_message_id: String((last && last.message_id) || ''),
  guard_buffer_last_message_text: (last && (last.data || last.content_text)) || ''
});
return [{ json: output }];

const reply = $json.output?.reply || {};
const hints = reply.channel_hints || {};
const supportsMeta = Boolean($json.supports_meta_interactive);
const primaryIntent = String($json.conversation_intent?.primary_intent || '').trim();
const selectedModel = String($json.selected_model || $json.mcp_booking_state?.selected_model || '').trim();
const fallbackText = String(hints.fallback_text || reply.text || '').trim();
const replyText = String(reply.text || fallbackText).trim();
const privateNoteSummary = String(hints.private_note_summary || '').trim();
const ctaQuestion = String(hints.cta_question || '').trim();
const policy = String(hints.interactive_policy || '').trim() || 'prefer_text_only';
const catalogItems = Array.isArray(hints.catalog_items) ? hints.catalog_items.filter(Boolean) : [];
const quickReplies = Array.isArray(hints.quick_replies) ? hints.quick_replies.filter(Boolean) : [];
const listItems = Array.isArray(hints.list_items) ? hints.list_items.filter(Boolean) : [];
function digitsPhone(value) {
  const raw = String(value || '').trim();
  if (!raw || /^wamid\./i.test(raw)) return '';
  const digits = raw.replace(/[^0-9]/g, '');
  return digits.length >= 8 ? digits : '';
}

const editFields = $('Edit Fields').item.json || {};
const webhookBody = $('Webhook').item.json.body || {};
const phone = [
  $json.recipient_wa_id,
  $json.conversation?.contact_inbox?.source_id,
  editFields.body?.conversation?.contact_inbox?.source_id,
  webhookBody.conversation?.contact_inbox?.source_id,
  editFields.body?.conversation?.meta?.sender?.phone_number,
  webhookBody.conversation?.meta?.sender?.phone_number,
  editFields.body?.sender?.phone_number,
  webhookBody.sender?.phone_number,
  $json.channel?.source_id,
  $json.mcp_booking_state?.channel?.source_id,
  $json.contact_context?.phone_number,
].map(digitsPhone).find(Boolean) || '';

function slug(text) {
  return String(text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 40) || 'opcion';
}

function short(text, max = 120) {
  const value = String(text || '').trim();
  return value.length > max ? value.slice(0, max - 1) + '…' : value;
}

const normalizedCatalog = catalogItems
  .map((item, idx) => ({
    id: String(item.id || `${idx + 1}`),
    name: String(item.name || '').trim(),
    subtitle: short(item.subtitle || ''),
    image_url: String(item.image_url || '').trim(),
    techsheet_url: String(item.techsheet_url || '').trim(),
    category: String(item.category || '').trim(),
  }))
  .filter((item) => item.name);

const normalizedQuickReplies = (quickReplies.length ? quickReplies : [
  { id: 'mas_info', title: 'Más info' },
  { id: 'ver_en_persona', title: 'Verlo en persona' },
])
  .map((item) => ({ id: slug(item.id || item.title), title: short(item.title || 'Opción', 20) }))
  .slice(0, 3);

const normalizedListItems = listItems
  .map((item, idx) => ({
    id: String(item.id || `${idx + 1}`),
    title: short(item.title || `Opción ${idx + 1}`, 24),
    description: short(item.description || '', 72),
