  .filter((item) => item.title);

let strategy = {
  delivery_route: 'chat_text',
  interactive_type: 'none',
  delivery_text: fallbackText || replyText,
  private_note_content: '',
  strategy_reason: 'text_default',
  meta_request_body: null,
  delivery_attachments: Array.isArray(hints.attachments) ? hints.attachments : [],
};

if (!supportsMeta) {
  return [{ json: { ...$json, ...strategy } }];
}

if (policy === 'prefer_carousel' && normalizedCatalog.length >= 2) {
  const cards = normalizedCatalog.slice(0, 10).map((item, idx) => ({
    card_index: idx,
    type: 'cta_url',
    header: { type: 'image', image: { link: item.image_url } },
    body: { text: short(item.name + (item.subtitle ? '\n' + item.subtitle : ''), 160) },
    action: {
      buttons: [
        { type: 'quick_reply', quick_reply: { id: slug(item.name) + '__mas_info', title: 'Más info' } },
        { type: 'quick_reply', quick_reply: { id: slug(item.name) + '__verlo_en_persona', title: 'Verlo en persona' } },
      ],
    },
  })).filter((card) => card.header.image.link);

  if (cards.length >= 2) {
    strategy = {
      delivery_route: 'meta_interactive',
      interactive_type: 'carousel',
      delivery_text: replyText || 'Te comparto algunas opciones destacadas.',
      private_note_content: privateNoteSummary || `Carrusel enviado con ${cards.length} vehículos para consulta de catálogo.`,
      strategy_reason: 'vehicle_family_carousel',
      meta_request_body: {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: phone,
        type: 'interactive',
        interactive: {
          type: 'carousel',
          body: { text: short(replyText || 'Te comparto algunas opciones destacadas.', 1024) },
          action: { cards },
        },
      },
      delivery_attachments: [],
    };
    return [{ json: { ...$json, ...strategy } }];
  }
}

if ((policy === 'prefer_quick_reply_test_drive' || (primaryIntent === 'vehicle_info' && (selectedModel || normalizedCatalog.length === 1))) && normalizedQuickReplies.length >= 2) {
  const question = ctaQuestion || (selectedModel
    ? `¿Te gustaría conocer más de ${selectedModel} o verlo en persona?`
    : '¿Quieres más información o prefieres verlo en persona?');

  strategy = {
    delivery_route: 'meta_interactive',
    interactive_type: 'button',
    delivery_text: replyText || question,
    private_note_content: privateNoteSummary || 'Botones rápidos enviados para continuar la conversación comercial del vehículo.',
    strategy_reason: 'vehicle_detail_quick_reply',
    meta_request_body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'button',
        body: { text: short((replyText ? replyText + '\n\n' : '') + question, 1024) },
        action: {
          buttons: normalizedQuickReplies.map((item) => ({ type: 'reply', reply: { id: item.id, title: item.title } })),
        },
      },
    },
    delivery_attachments: [],
  };
  return [{ json: { ...$json, ...strategy } }];
}

if (policy === 'prefer_list' && normalizedListItems.length >= 2) {
  strategy = {
    delivery_route: 'meta_interactive',
    interactive_type: 'list',
    delivery_text: replyText || 'Te comparto opciones para que elijas.',
    private_note_content: privateNoteSummary || `Lista interactiva enviada con ${normalizedListItems.length} opciones.`,
    strategy_reason: 'multi_option_list',
    meta_request_body: {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: phone,
      type: 'interactive',
      interactive: {
        type: 'list',
        body: { text: short(replyText || 'Te comparto opciones para que elijas.', 1024) },
        action: { button: 'Ver opciones', sections: [{ title: 'Opciones', rows: normalizedListItems.slice(0, 10) }] },
      },
    },
    delivery_attachments: [],
  };
  return [{ json: { ...$json, ...strategy } }];
}

return [{ json: { ...$json, ...strategy } }];

const builtItems = $items('Prepare Welcome Model Info Attachment');

return $input.all().map((item, index) => {
  const paired = Array.isArray(item.pairedItem) ? item.pairedItem[0] : item.pairedItem;
  const sourceIndex = Number.isInteger(Number(paired?.item)) ? Number(paired.item) : index;
  const built = (builtItems[sourceIndex] || builtItems[index] || {}).json || {};

  return {
    json: {
      ...built,
      welcome_persist_result: item.json || {},
    },
    pairedItem: { item: index },
  };
