const node = (name) => {
  try { return $(name).item.json || {}; }
  catch (error) { return {}; }
};
const classified = node('Set Conversation Intent');
const journey = node('Set Journey Context');
const base = Object.keys(classified).length ? classified : journey;
const response = $json || {};
const responseAction = response.next_action || {};

function normalizeText(value) {
  return String(value || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const primaryIntent = normalizeText(base.conversation_intent?.primary_intent).replace(/ /g, '_');
const latestMessage = ` ${normalizeText(base.concat_message)} `;
const financingRequested = [
  'financing',
  'financing_info',
  'financiamiento',
  'credito',
].includes(primaryIntent) || [
  ' financiam',
  ' financiacion ',
  ' financiar',
  ' credito ',
  ' creditos ',
  ' cuota ',
  ' cuotas ',
  ' mensualidad ',
  ' mensualidades ',
  ' tasa de interes ',
  ' pago mensual ',
  ' cuanto de entrada ',
  ' valor de entrada ',
].some((marker) => latestMessage.includes(marker));

let action = responseAction;
let nextActionResponse = response;

const rawLatestMessage = String(base.concat_message || '');
const moreInfoRequested = /button_action:\s*mas_info/i.test(rawLatestMessage)
  || /__mas_info\b/i.test(rawLatestMessage);
const hasValidSendModelInfo = String(responseAction.type || '').trim() === 'send_model_info'
  && String(responseAction.text || '').trim().length > 0;
if (moreInfoRequested && !hasValidSendModelInfo) {
  const moreInfoState = base.mcp_booking_state || {};
  const moreInfoAttrs = base.conversation?.custom_attributes || {};
  const responseJourney = response.journey || {};
  const trueValue = (value) => value === true || ['1', 'true', 'yes', 'si'].includes(String(value || '').trim().toLowerCase());
  const profileComplete = trueValue(
    responseJourney.booking_personal_data_complete
    || moreInfoState.booking_personal_data_complete
    || moreInfoAttrs.booking_personal_data_complete
  );
  const selectedModelId = Number(
    responseJourney.selected_model_id
    || response.attributes_to_merge?.selected_model_id
    || moreInfoState.selected_model_id
    || moreInfoAttrs.selected_model_id
    || 0
  );

  if (profileComplete && Number.isInteger(selectedModelId) && selectedModelId > 0) {
    try {
      const detailResponse = await $helpers.httpRequest({
        method: 'POST',
        url: 'http://mcp_server:8000/api/product-resolve',
        headers: { 'Content-Type': 'application/json' },
        body: {
          current_selected_model_id: selectedModelId,
          reviewed_model_ids: Array.isArray(responseJourney.reviewed_model_ids) ? responseJourney.reviewed_model_ids : [],
          limit: 1,
        },
        json: true,
      });
      const product = detailResponse?.best_match || {};
      if (!detailResponse?.ok || !product?.id) throw new Error('product_detail_not_found');

      const cleanMoreInfoText = (value) => String(value || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
      const detailValue = (...keys) => {
        for (const key of keys) {
          const value = product[key];
          if (Array.isArray(value) && value.length) return value.join(', ');
          if (value !== null && value !== undefined && cleanMoreInfoText(value)) return value;
        }
        return null;
      };
      const assetUrls = (keys) => {
        const urls = [];
        for (const key of keys) {
          const value = product[key];
          const values = Array.isArray(value) ? value : String(value || '').split(/[\n,;]/);
          for (const candidate of values) {
            const url = String(candidate || '').trim();
            if (/^https?:\/\//i.test(url) && !urls.includes(url)) urls.push(url);
          }
        }
        return urls;
      };

      const modelName = cleanMoreInfoText(product.name || responseJourney.selected_model || moreInfoState.selected_model || 'Hyundai');
      const description = cleanMoreInfoText(detailValue('description', 'descripcion', 'summary'));
      const specPairs = [
        ['Motor', detailValue('engine', 'motor')],
        ['Potencia / torque', detailValue('torque', 'horsepower', 'power')],
        ['Transmisión', detailValue('transmision', 'transmission', 'speeds')],
        ['Tracción', detailValue('traction', 'traccion')],
        ['Seguridad', detailValue('airbags', 'safety', 'seguridad')],
        ['Pantalla', detailValue('touch_screen', 'screen', 'pantalla')],
        ['Cámara', detailValue('camera', 'camara')],
        ['Audio', detailValue('sound_system', 'audio')],
      ];
      const specLines = specPairs
        .map(([label, value]) => value ? `• ${label}: ${cleanMoreInfoText(value)}` : '')
        .filter(Boolean)
        .slice(0, 8);
      const lines = [`🚙 ${modelName}`, '', description || 'Una opción Hyundai pensada para combinar desempeño, comodidad y tecnología en cada trayecto.'];
      if (specLines.length) lines.push('', '⭐ Lo más destacado', '', ...specLines);

      const rawPrice = detailValue('price_from', 'sale_price', 'price', 'pvp');
      if (rawPrice !== null) {
        const numericPrice = Number(String(rawPrice).replace(/[^0-9.-]/g, ''));
        const priceText = Number.isFinite(numericPrice)
          ? `$${numericPrice.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
          : cleanMoreInfoText(rawPrice);
        lines.push('', '💰 Precio referencial', priceText);
      }

      const techsheetUrls = assetUrls(['techsheet_url', 'pdf_url', 'brochure_url', 'site_url', 'product_url', 'url']);
      if (techsheetUrls.length) lines.push('', '📄 Ficha técnica', 'Te adjunto el PDF con todas las especificaciones para que puedas revisarlas con detalle.');
      lines.push('', '🚗 ¿Qué sigue?', '', 'Las especificaciones cuentan una parte de la historia.', 'La verdadera experiencia comienza cuando lo enciendes y sientes cómo responde.', '', `¿Te gustaría conocer el ${modelName} en persona?`);

      const slug = modelName
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '') || `hyundai_${selectedModelId}`;
      action = {
        type: 'send_model_info',
        text: lines.join('\n'),
        model_id: Number(product.id) || selectedModelId,
        model_name: modelName,
        image_urls: assetUrls(['image1', 'image2', 'image3', 'main_image_url', 'image_url', 'photo_url', 'main_image', 'image']),
        techsheet_urls: techsheetUrls,
        quick_replies: [{ id: `${slug}__ver_en_persona`, title: 'Ver en persona', action: 'ver_en_persona' }],
        reason: 'catalog_more_info',
      };
    } catch (error) {
      action = {
        type: 'send_text_prompt',
        text: 'Dame un momento para verificar la ficha exacta de ese modelo y no fallarte con la información.',
        reason: 'product_get_failed',
      };
      response.more_info_fallback_error = String(error?.message || error || 'product_detail_failed').slice(0, 180);
    }

    const existingLabels = Array.isArray(response.labels_result?.labels)
      ? response.labels_result.labels
      : (Array.isArray(base.conversation?.labels) ? base.conversation.labels : []);
    const correctedLabels = [...new Set([
      ...existingLabels.filter((label) => String(label || '').trim() !== 'dealer_pending'),
      'vehicle_info_requested',
    ].map((label) => String(label || '').trim()).filter(Boolean))];
    const labelsToAdd = [...new Set([
      ...(Array.isArray(response.labels_to_add) ? response.labels_to_add : []).filter((label) => label !== 'dealer_pending'),
      'vehicle_info_requested',
    ])];
    nextActionResponse = {
      ...response,
      next_action: action,
      labels_to_add: labelsToAdd,
      labels_to_remove: [...new Set([...(Array.isArray(response.labels_to_remove) ? response.labels_to_remove : []), 'dealer_pending'])],
      labels_result: { ...(response.labels_result || {}), labels: correctedLabels },
      more_info_runtime_fallback: true,
    };

    const editFields = $items('Edit Fields')[0]?.json || {};
    const chatwootBase = String(editFields.URL_OMNICEM || '').replace(/\/+$/, '');
    const chatwootAccountId = Number(editFields.account_id || 0);
    const chatwootConversationId = Number(editFields.sessionId || 0);
    const chatwootToken = String(editFields.TOKEN_ADMIN || editFields.TOKEN || '').trim();
    if (chatwootBase && chatwootAccountId && chatwootConversationId && chatwootToken) {
      try {
        await $helpers.httpRequest({
          method: 'POST',
          url: `${chatwootBase}/api/v1/accounts/${chatwootAccountId}/conversations/${chatwootConversationId}/labels`,
          headers: { api_access_token: chatwootToken, 'Content-Type': 'application/json' },
          body: { labels: correctedLabels },
          json: true,
        });
      } catch (error) {
        nextActionResponse.more_info_label_sync_error = String(error?.message || error || 'label_sync_failed').slice(0, 180);
      }
    }
  }
}
if (financingRequested && !moreInfoRequested) {
  const responseJourney = response.journey || {};
  const attrs = base.conversation?.custom_attributes || {};
  const selectedModel = String(
    responseJourney.selected_model
    || base.selected_model
    || base.mcp_booking_state?.selected_model
    || attrs.selected_model
    || '',
  ).trim();
  const bookingInProgress = responseAction.flow_name === 'fecha_agendamiento'
    || ['datos_basicos', 'datos_basicos_TAC', 'fecha_agendamiento'].includes(String(attrs.booking_flow_sent_type || ''))
    || ['collect_schedule', 'appointment_ready'].includes(String(attrs.booking_phase || ''))
    || String(attrs.appointment_offer_status || '') === 'phase6_flow_sent';
  const vehicleText = selectedModel
    ? `en persona el modelo ${selectedModel}`
    : 'el vehículo de tu interés';
  let text = `Sí, contamos con opciones de financiamiento. Agenda una cita para conocer ${vehicleText} y, durante la visita, un asesor te guiará con las alternativas y el proceso de financiamiento.`;
  if (bookingInProgress) {
    text += ' Puedes continuar con el formulario de agendamiento que te compartí.';
  } else if (selectedModel) {
    text += ' ¿Quieres que te ayude a agendar?';
  } else {
    text += ' ¿Qué modelo Hyundai te interesa?';
  }

  action = {
    type: 'send_text_prompt',
    text,
