function isWeekendIsoDate(value) {
  const [year, month, day] = String(value || '').slice(0, 10).split('-').map(Number);
  if (!year || !month || !day) return false;
  const weekday = new Date(Date.UTC(year, month - 1, day)).getUTCDay();
  return weekday === 0 || weekday === 6;
}

function nextBusinessIsoDateAfter(value) {
  const [year, month, day] = String(value || '').slice(0, 10).split('-').map(Number);
  const baseDate = year && month && day ? new Date(Date.UTC(year, month - 1, day)) : new Date();
  for (let offset = 1; offset <= 14; offset += 1) {
    const candidate = new Date(baseDate.getTime() + offset * 24 * 60 * 60 * 1000);
    const weekday = candidate.getUTCDay();
    if (weekday !== 0 && weekday !== 6) {
      return candidate.toISOString().slice(0, 10);
    }
  }
  return new Date(baseDate.getTime() + 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
}

