    next_action_response: nextActionResponse,
    next_action: action,
    mcp_next_action_labels: nextActionResponse.labels_to_add || [],
    mcp_next_action_labels_result: nextActionResponse.labels_result || null,
  },
}];

const ALLOWED_FIELDS = new Set([
  'flow_name',
  'flow_token',
  'name',
  'identifier',
  'email',
  'phone',
  'city',
  'intent',
  'comments',
  'selected_model',
  'selected_model_id',
  'selected_establishment',
  'selected_establishment_id',
  'selected_establishment_name',
  'selected_date',
  'selected_time',
  'purchase_timeframe_days',
]);

const PROFILE_FIELDS = new Set([
  'name',
  'identifier',
  'email',
  'phone',
  'city',
  'selected_establishment',
  'selected_establishment_id',
  'selected_establishment_name',
  'intent',
  'comments',
  'purchase_timeframe_days',
]);

const APPOINTMENT_FIELDS = new Set([
  'selected_model',
  'selected_model_id',
  'selected_establishment',
  'selected_establishment_id',
  'selected_establishment_name',
  'selected_date',
  'selected_time',
  'purchase_timeframe_days',
]);

function getNodeJson(name) {
  try {
    return $(name).item.json || {};
  } catch {
    return {};
  }
}

function canonicalFlowName(value) {
  const text = String(value || '').trim().toLowerCase();
  if (text === 'datos_basicos_tac') return 'datos_basicos_TAC';
  if (text === 'datos_basicos') return 'datos_basicos';
  if (text === 'fecha_agendamiento') return 'fecha_agendamiento';
  return '';
}

function parseCurrentMessage(value) {
  const fields = {};
  for (const line of String(value || '').replace(/\r/g, '').split('\n')) {
    const match = line.match(/^\s*([A-Za-z_]+)\s*:\s*(.*?)\s*$/);
    if (!match) continue;
    const key = match[1].toLowerCase();
    const fieldName = key === 'flow_name' ? 'flow_name' : key;
    if (!ALLOWED_FIELDS.has(fieldName) || fields[fieldName]) continue;
    const fieldValue = String(match[2] || '').trim();
    if (fieldValue) fields[fieldName] = fieldValue;
  }
  return fields;
}

const editFields = getNodeJson('Edit Fields');
const webhook = getNodeJson('Webhook');
const buffer = getNodeJson('Concatenar Buffer');
const base = getNodeJson('Set Journey Context');
const currentMessage = String(
  buffer.buffer_last_message_text ||
  webhook.body?.content ||
  ''
).trim();
const fields = parseCurrentMessage(currentMessage);
const flowToken = String(fields.flow_token || '').trim();
const flowName = canonicalFlowName(fields.flow_name) || canonicalFlowName(flowToken.split('-')[0]);
const schema = flowName === 'fecha_agendamiento' ? APPOINTMENT_FIELDS : PROFILE_FIELDS;
const answers = {};
for (const key of schema) {
  if (fields[key]) answers[key] = fields[key];
}
if (flowToken) answers.flow_token = flowToken;

return [{
  json: {
    ...base,
    flow_submit_detected: Boolean(flowName && flowToken),
    flow_submit_payload: {
      conversation_id: editFields.sessionId,
      account_id: editFields.account_id,
      conversation_display_id: editFields.conversation_display_id,
      flow_name: flowName,
      flow_token: flowToken,
      answers,
      persist: true,
      sync_labels: true,
      include_next_action: false,
      auto_create_appointment: false,
      api_access_token: editFields.TOKEN_ADMIN || editFields.TOKEN,
    },
  },
}];

const inputItems = $input.all();

function clean(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function truncate(value, max) {
  const text = clean(value);
  return text.length > max ? text.slice(0, Math.max(0, max - 3)).trimEnd() + '...' : text;
}

function firstPdfUrl(action) {
  const urls = Array.isArray(action.techsheet_urls) ? action.techsheet_urls : [];
  return urls
    .map((url) => String(url || '').trim())
    .find((url) => url.toLowerCase().startsWith('http://') || url.toLowerCase().startsWith('https://')) || '';
}

return inputItems.map((item, index) => {
  const source = item.json || {};
  const action = source.next_action || {};
  const actionType = String(action.type || '').trim();
  const pdfUrl = firstPdfUrl(action);
  const pairedItem = item.pairedItem || { item: index };

  if (actionType !== 'send_model_info' || !pdfUrl) {
    return { json: source, pairedItem };
  }

  const modelName = clean(action.model_name || source.selected_model || 'Hyundai');
  const rawRecipient = clean((source.meta_request_body && source.meta_request_body.to) || source.recipient_wa_id);
  const recipient = rawRecipient.replace(/[^0-9]/g, '');
  const filenameBase = clean(modelName)
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9_-]+/g, '_')
    .replace(/^_+|_+$/g, '') || 'ficha_tecnica_hyundai';
  const existing = Array.isArray(source.delivery_attachments) ? source.delivery_attachments : [];
  const output = {
    ...source,
    delivery_attachments: [...existing, { type: 'document', url: pdfUrl }],
  };

  if (recipient) {
    output.meta_document_request_body = {
      messaging_product: 'whatsapp',
      recipient_type: 'individual',
      to: recipient,
      type: 'document',
      document: {
        link: pdfUrl,
        caption: truncate('Ficha tecnica ' + modelName, 1024),
        filename: filenameBase + '.pdf',
      },
    };
    const note = clean(source.private_note_content);
    const pdfNote = 'Ficha tecnica PDF: adjunto enviado por Meta WhatsApp.';
    output.private_note_content = note ? note + '\n\n' + pdfNote : pdfNote;
  }

  return { json: output, pairedItem };
});

