const registration = $json.meta_request_body || {};
const messages = Array.isArray(registration.messages) ? registration.messages : [];
const graphPhoneId = String(registration.graph_phone_number_id || $json.meta_phone_number_id || '').trim();
const graphToken = String(registration.meta_access_token || $json.meta_access_token || '').trim();

if (!messages.length || !graphPhoneId || !graphToken) {
  return [{
    json: {
      ...$json,
      queue_fallback_skipped: true,
      queue_fallback_reason: 'missing_messages_or_meta_credentials',
    },
  }];
}

return messages
  .map((message, index) => ({
    json: {
      ...$json,
      queue_fallback_active: true,
      queue_fallback_index: index,
      queue_fallback_kind: String(message.kind || message.body?.type || `message_${index + 1}`),
      delivery_route: 'meta_interactive',
      meta_target_url: `https://graph.facebook.com/v23.0/${graphPhoneId}/messages`,
      meta_phone_number_id: graphPhoneId,
      meta_access_token: graphToken,
      meta_request_body: message.body,
      private_note_content: `Fallback directo enviado para mensaje ${index + 1} porque no se pudo registrar la cola secuencial.`,
    },
  }))
  .filter((item) => item.json.meta_request_body);
